import React, { useCallback, useEffect, useMemo, useRef, useState, type ReactNode } from 'react';
import { AccessibilityInfo, PanResponder, Platform, StyleSheet, View, type AccessibilityActionEvent, type LayoutChangeEvent } from 'react-native';
import { Canvas, Fill, Shader, Skia } from '@shopify/react-native-skia';
import { useDerivedValue, useSharedValue, withSpring, withTiming } from 'react-native-reanimated';
import { lensTarget, lensUniforms, type LensConfig } from './lensMath';

export type LensSize = { width: number; height: number };
export type LensFeedback = 'grab' | 'release';
export type GlassLensProps = {
  width: number;
  height: number;
  /** The scene the lens looks through: a Skia shader node such as <LinearGradient />, <ImageShader /> or your own <Shader />. Sized by the box. */
  backdrop: (size: LensSize) => ReactNode;
  /** RN content drawn above the canvas. It never receives touches and is not bent by the lens. */
  overlay?: ReactNode;
  radius?: number;
  /** Magnification at the centre, 0 to 0.7. 0.45 is about 1.8x. */
  strength?: number;
  /** Colour fringing at the rim, 0 to 0.06. */
  aberration?: number;
  label?: string;
  onMove?: (point: { x: number; y: number }) => void;
  onFeedback?: (event: LensFeedback) => void;
  reducedMotion?: boolean;
};

// The same maths as lensMath.ts. The lens is a dome with a bevel: inside it the backdrop is sampled closer to the
// centre (magnified), the red and blue channels are sampled at slightly different scales (colour fringe), and the
// rim gets a light from the upper left. The lens stretches along the way it is moving.
const SOURCE = `
uniform shader src;
uniform float2 center;
uniform float radius;
uniform float strength;
uniform float aberration;
uniform float2 axis;
uniform float stretch;
half4 main(float2 p) {
  half4 base = src.eval(p);
  if (radius < 0.5) return base;
  float2 delta = p - center;
  float along = dot(delta, axis) / (1.0 + stretch);
  float across = (-delta.x * axis.y + delta.y * axis.x) * (1.0 + stretch * 0.5);
  float d = sqrt(along * along + across * across);
  float n = d / radius;
  float nc = min(n, 1.0);
  float cover = 1.0 - smoothstep(radius - 1.5, radius, d);
  float shadow = n > 1.0 ? exp(-(d - radius) / (0.28 * radius)) * 0.22 : 0.0;
  float bevel = smoothstep(0.78, 1.0, nc);
  float s = 1.0 - strength * (1.0 - nc * nc) + bevel * 0.18;
  float fringe = aberration * (0.4 + nc);
  half4 cr = src.eval(center + delta * (s * (1.0 - fringe)));
  half4 cg = src.eval(center + delta * s);
  half4 cb = src.eval(center + delta * (s * (1.0 + fringe)));
  half3 glass = half3(cr.r, cg.g, cb.b);
  float len = max(length(delta), 0.0001);
  float facing = dot(delta / len, float2(-0.6, -0.8));
  float rim = bevel * (pow(max(0.0, facing), 2.0) * 0.55 + pow(max(0.0, -facing), 3.0) * 0.25);
  float gloss = smoothstep(0.45, 0.0, distance(delta / radius, float2(-0.35, -0.4))) * 0.12;
  glass = min(glass + half3(half(n <= 1.0 ? rim + gloss : 0.0)), half3(1.0));
  half3 outside = base.rgb * half(1.0 - shadow);
  return half4(mix(outside, glass, half(cover)), 1.0);
}`;
const effect = Skia.RuntimeEffect.Make(SOURCE);
const STEP = 24;

export function GlassLens({ width, height, backdrop, overlay, radius = 62, strength = 0.45, aberration = 0.03, label = 'Glass lens', onMove, onFeedback, reducedMotion }: GlassLensProps) {
  const [systemReduce, setSystemReduce] = useState(false);
  const reduce = reducedMotion ?? systemReduce;
  const cx = useSharedValue(width * 0.62), cy = useSharedValue(height * 0.42);
  const tx = useSharedValue(width * 0.62), ty = useSharedValue(height * 0.42);
  const grow = useSharedValue(1);
  const origin = useRef({ x: 0, y: 0 });
  const latest = useRef({ onMove, onFeedback, reduce, width, height });
  latest.current = { onMove, onFeedback, reduce, width, height };
  useEffect(() => {
    let alive = true;
    AccessibilityInfo.isReduceMotionEnabled().then(v => { if (alive) setSystemReduce(v); }).catch(() => {});
    const sub = AccessibilityInfo.addEventListener('reduceMotionChanged', setSystemReduce);
    return () => { alive = false; sub.remove(); };
  }, []);
  const cfg = useMemo<LensConfig>(() => ({ width, height, radius, strength, aberration }), [width, height, radius, strength, aberration]);
  const uniforms = useDerivedValue(() => lensUniforms(cx.value, cy.value, tx.value, ty.value, grow.value, reduce, cfg));
  // The target is where the finger is. The visible lens follows it on a spring, so quick moves lag, overshoot and stretch.
  const goTo = useCallback((x: number, y: number) => {
    const t = lensTarget(x, y, latest.current.width, latest.current.height);
    tx.value = t.x;
    ty.value = t.y;
    if (latest.current.reduce) { cx.value = withTiming(t.x, { duration: 90 }); cy.value = withTiming(t.y, { duration: 90 }); }
    else { cx.value = withSpring(t.x, { stiffness: 170, damping: 15, mass: 1 }); cy.value = withSpring(t.y, { stiffness: 170, damping: 15, mass: 1 }); }
    latest.current.onMove?.(t);
  }, [cx, cy, tx, ty]);
  const setGrow = useCallback((value: number) => {
    grow.value = latest.current.reduce ? withTiming(value, { duration: 90 }) : withSpring(value, { stiffness: 220, damping: 14, mass: 1 });
  }, [grow]);
  const pan = useMemo(() => PanResponder.create({
    onStartShouldSetPanResponder: () => true,
    onMoveShouldSetPanResponder: () => true,
    onPanResponderTerminationRequest: () => false,
    onPanResponderGrant: event => {
      const e = event.nativeEvent;
      origin.current = { x: e.locationX, y: e.locationY };
      goTo(e.locationX, e.locationY);
      setGrow(1.14);
      latest.current.onFeedback?.('grab');
    },
    onPanResponderMove: (_event, g) => goTo(origin.current.x + g.dx, origin.current.y + g.dy),
    onPanResponderRelease: () => { setGrow(1); latest.current.onFeedback?.('release'); },
    onPanResponderTerminate: () => setGrow(1),
  }), [goTo, setGrow]);
  // Screen readers and the keyboard nudge the lens in steps.
  const nudge = useCallback((dx: number, dy: number) => goTo(tx.value + dx, ty.value + dy), [goTo, tx, ty]);
  const onAction = useCallback((event: AccessibilityActionEvent) => {
    const name = event.nativeEvent.actionName;
    if (name === 'left') nudge(-STEP, 0); else if (name === 'right') nudge(STEP, 0); else if (name === 'up') nudge(0, -STEP); else if (name === 'down') nudge(0, STEP);
  }, [nudge]);
  const onKey = useCallback((event: { key?: string; nativeEvent?: { key?: string }; preventDefault?: () => void }) => {
    const key = event.key ?? event.nativeEvent?.key;
    const map: Record<string, [number, number]> = { ArrowLeft: [-STEP, 0], ArrowRight: [STEP, 0], ArrowUp: [0, -STEP], ArrowDown: [0, STEP] };
    if (key && map[key]) { event.preventDefault?.(); nudge(map[key][0], map[key][1]); }
  }, [nudge]);
  const onLayout = useCallback((_e: LayoutChangeEvent) => {}, []);
  const size = { width, height };
  const webProps = Platform.OS === 'web' ? ({ focusable: true, tabIndex: 0, onKeyDown: onKey } as object) : {};
  return (
    <View style={{ width, height, borderRadius: 22, overflow: 'hidden', alignSelf: 'center' }} onLayout={onLayout}>
      <Canvas pointerEvents="none" style={styles.fill}>
        <Fill>
          {effect ? <Shader source={effect} uniforms={uniforms}>{backdrop(size)}</Shader> : null}
        </Fill>
      </Canvas>
      <View pointerEvents="none" style={styles.fill}>{overlay}</View>
      <View
        accessible
        accessibilityRole="adjustable"
        accessibilityLabel={label}
        accessibilityHint="Drag to move the lens. Swipe up or down with a screen reader to nudge it."
        accessibilityActions={[{ name: 'left', label: 'Move lens left' }, { name: 'right', label: 'Move lens right' }, { name: 'up', label: 'Move lens up' }, { name: 'down', label: 'Move lens down' }]}
        onAccessibilityAction={onAction}
        style={styles.fill}
        {...pan.panHandlers}
        {...webProps}
      />
    </View>
  );
}
const styles = StyleSheet.create({ fill: { position: 'absolute', left: 0, top: 0, right: 0, bottom: 0 } });

// Pure geometry for the Glass Lens. Every function is a worklet so Skia and
// Reanimated can call it on the UI thread; plain JS (tests, web preview) ignores the tag.
export type LensConfig = { width: number; height: number; radius: number; strength: number; aberration: number };
export type LensPoint = { x: number; y: number };

export function clamp(value: number, min: number, max: number) {
  'worklet';
  return Math.max(min, Math.min(max, Number.isFinite(value) ? value : min));
}
// The lens centre stays inside the box. A bad point falls back to the middle.
export function lensTarget(x: number, y: number, width: number, height: number): LensPoint {
  'worklet';
  if (!Number.isFinite(x) || !Number.isFinite(y)) return { x: width / 2, y: height / 2 };
  return { x: clamp(x, 0, width), y: clamp(y, 0, height) };
}
// The lens trails the finger on a spring. The gap between the two stretches it along the way it travels.
export const MAX_STRETCH = 0.38;
export function stretchFrom(cx: number, cy: number, tx: number, ty: number, reduce: boolean) {
  'worklet';
  const dx = tx - cx, dy = ty - cy, lag = Math.sqrt(dx * dx + dy * dy);
  if (reduce || lag < 0.5) return { stretch: 0, ax: 1, ay: 0 };
  return { stretch: Math.min(MAX_STRETCH, lag / 240), ax: dx / lag, ay: dy / lag };
}
// Everything the shader needs, in the order the SkSL declares it. `grow` is 0 (hidden) to 1 (full size).
export function lensUniforms(cx: number, cy: number, tx: number, ty: number, grow: number, reduce: boolean, cfg: LensConfig) {
  'worklet';
  const s = stretchFrom(cx, cy, tx, ty, reduce);
  return {
    center: [cx, cy],
    radius: cfg.radius * clamp(grow, 0, 1.3),
    strength: cfg.strength,
    aberration: reduce ? 0 : cfg.aberration,
    axis: [s.ax, s.ay],
    stretch: s.stretch,
  };
}
// Distance in the lens's own (stretched) space. 1 is the rim.
export function lensDistance(px: number, py: number, u: ReturnType<typeof lensUniforms>) {
  'worklet';
  const dx = px - u.center[0], dy = py - u.center[1];
  const along = dx * u.axis[0] + dy * u.axis[1];
  const across = -dx * u.axis[1] + dy * u.axis[0];
  const a = along / (1 + u.stretch), b = across * (1 + u.stretch * 0.5);
  return Math.sqrt(a * a + b * b);
}
export function smoothstep(a: number, b: number, x: number) {
  'worklet';
  const t = clamp((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
}
// Scale applied to the offset from the centre when sampling the backdrop.
// Below 1 magnifies. The dome is strongest in the middle and eases to 1 at the rim, where a bevel bends the view back out.
export function sampleScale(n: number, strength: number) {
  'worklet';
  const dome = strength * (1 - n * n);
  const bevel = smoothstep(0.78, 1, n) * 0.18;
  return 1 - dome + bevel;
}
// One pixel of the lens in plain JS. The web preview runs this; the SkSL mirrors it.
// r, g and b are the three sample positions (colour fringes), `cover` is how much of the lens is here, `light` the rim highlight, `shadow` the soft drop shadow outside.
export function samplePoint(px: number, py: number, u: ReturnType<typeof lensUniforms>) {
  'worklet';
  const R = u.radius;
  if (R < 0.5) return { r: { x: px, y: py }, g: { x: px, y: py }, b: { x: px, y: py }, cover: 0, light: 0, shadow: 0 };
  const dx = px - u.center[0], dy = py - u.center[1];
  const d = lensDistance(px, py, u);
  const n = d / R;
  const cover = 1 - smoothstep(R - 1.5, R, d);
  const shadow = n > 1 ? Math.exp(-(d - R) / (0.28 * R)) * 0.22 : 0;
  const s = sampleScale(Math.min(n, 1), u.strength);
  const fringe = u.aberration * (0.4 + Math.min(n, 1));
  const at = (k: number) => ({ x: u.center[0] + dx * k, y: u.center[1] + dy * k });
  const bevel = smoothstep(0.78, 1, Math.min(n, 1));
  const len = Math.sqrt(dx * dx + dy * dy) || 1;
  const lx = -0.6, ly = -0.8;
  const facing = (dx / len) * lx + (dy / len) * ly;
  const rim = bevel * (Math.pow(Math.max(0, facing), 2) * 0.55 + Math.pow(Math.max(0, -facing), 3) * 0.25);
  const gloss = smoothstep(0.45, 0, Math.hypot(dx / R + 0.35, dy / R + 0.4)) * 0.12;
  return { r: at(s * (1 - fringe)), g: at(s), b: at(s * (1 + fringe)), cover, light: n <= 1 ? rim + gloss : 0, shadow };
}
// A spring step for the web preview and tests (the native side uses Reanimated withSpring). Semi-implicit Euler.
export function springStep(pos: number, vel: number, target: number, dt: number, stiffness = 170, damping = 15) {
  'worklet';
  const steps = Math.max(1, Math.ceil(dt / 0.004)), h = dt / steps;
  let p = pos, v = vel;
  for (let i = 0; i < steps; i++) { v += (stiffness * (target - p) - damping * v) * h; p += v * h; }
  return { pos: p, vel: v };
}

import React, { useMemo, useState } from 'react';
import { Pressable, Text, View } from 'react-native';
import { Shader, Skia } from '@shopify/react-native-skia';
import { GlassLens, type LensFeedback, type LensSize } from './GlassLens';

// An original "poster" drawn by one small SkSL shader: a gradient, a dot grid, fine rules and a few big rings.
// It is deliberately detailed so the lens has something to magnify and bend.
const ART = `
uniform float2 size;
half4 main(float2 p) {
  float2 uv = p / size;
  float3 c = mix(float3(0.06, 0.16, 0.2), float3(0.32, 0.2, 0.55), uv.x * 0.7 + uv.y * 0.5);
  c = mix(c, float3(0.98, 0.62, 0.38), smoothstep(0.65, 0.0, distance(uv, float2(0.85, 0.15))) * 0.8);
  float2 g = fract(p / 14.0) - 0.5;
  c = mix(c, float3(1.0), smoothstep(0.2, 0.12, length(g)) * 0.5);
  float rule = max(smoothstep(1.0, 0.0, abs(fract(p.x / 56.0 + 0.5) - 0.5) * 56.0), smoothstep(1.0, 0.0, abs(fract(p.y / 56.0 + 0.5) - 0.5) * 56.0));
  c = mix(c, float3(0.6, 0.95, 0.85), rule * 0.55);
  float ring = abs(distance(p, size * float2(0.3, 0.6)) - 46.0);
  c = mix(c, float3(1.0, 0.92, 0.6), smoothstep(2.5, 0.8, ring));
  float ring2 = abs(distance(p, size * float2(0.7, 0.75)) - 28.0);
  c = mix(c, float3(1.0, 0.5, 0.65), smoothstep(2.5, 0.8, ring2));
  return half4(half3(c), 1.0);
}`;
const art = Skia.RuntimeEffect.Make(ART);

export default function Example({ onFeedback }: { onFeedback?: (event: LensFeedback) => void }) {
  const [at, setAt] = useState({ x: 186, y: 84 });
  const [reduce, setReduce] = useState<boolean | undefined>();
  const backdrop = useMemo(() => ({ width, height }: LensSize) => art ? <Shader source={art} uniforms={{ size: [width, height] }} /> : null, []);
  return (
    <View style={{ paddingVertical: 24, width: '100%', alignItems: 'center' }}>
      <Text accessibilityLiveRegion="polite" style={{ color: '#31513b', fontSize: 13, marginBottom: 12 }}>Lens at {Math.round(at.x)}, {Math.round(at.y)}</Text>
      <GlassLens
        reducedMotion={reduce}
        width={300}
        height={200}
        backdrop={backdrop}
        label="Glass lens. Drag to move it over the poster."
        onMove={setAt}
        onFeedback={onFeedback}
        overlay={<View style={{ flex: 1, padding: 16, justifyContent: 'flex-end' }}><Text style={{ color: '#f4f1ff', fontSize: 13 }}>Drag the lens over the poster</Text></View>}
      />
      <Text style={{ color: '#4b6053', fontSize: 12, marginTop: 12 }}>Drag the lens over the poster.</Text>
      <Pressable accessibilityRole="switch" accessibilityState={{ checked: reduce === true }} accessibilityLabel="Reduced motion" onPress={() => setReduce(reduce === true ? undefined : true)} style={{ marginTop: 8, minHeight: 44, paddingHorizontal: 16, borderRadius: 14, backgroundColor: '#e6edde', justifyContent: 'center' }}><Text style={{ color: '#31513b', fontSize: 13 }}>Motion: {reduce === true ? 'reduced' : 'system'}</Text></Pressable>
    </View>
  );
}

# Glass Lens

Original touch-following glass lens. A round lens sits on a scene. Put a finger on it and drag: the lens grows a little, trails your finger on a spring, stretches along the way it moves, and bends the scene beneath it. The effect is one Skia runtime shader (SkSL) driven by Reanimated springs. No copied demo code or assets.

Copy `GlassLens.tsx` and `lensMath.ts` together and keep LICENSE.

```tsx
<GlassLens
  width={300}
  height={200}
  backdrop={({ width, height }) => <ImageShader image={image} fit="cover" rect={{ x: 0, y: 0, width, height }} />}
  overlay={<MyCaption />}
  radius={62}
  strength={0.45}
  aberration={0.03}
  onMove={point => console.log(point)}
/>
```

Dependencies: `@shopify/react-native-skia`, `react-native-reanimated` and `react-native-worklets` (Reanimated 4). In an Expo app run `npx expo install @shopify/react-native-skia react-native-reanimated react-native-worklets`. Skia runs on iOS, Android and web; on web it needs CanvasKit, see the Skia docs. Optional: `expo-haptics`, used only by the demo adapter.

How it works: the scene is a child shader of one runtime shader. For each pixel the shader measures the distance `n` from the lens centre, in units of the radius, after squeezing the space along the direction of travel. Inside the lens the scene is sampled at `center + offset * (1 - strength * (1 - n^2))`, which magnifies most at the middle and eases back to normal at the rim; a bevel near the rim bends the view back out. Red, green and blue are sampled at slightly different scales for the colour fringe. A light from the upper left adds a rim highlight and a soft gloss, and a short shadow falls outside. The lens position is a spring that chases the finger. The gap between the two sets the stretch. The geometry lives in `lensMath.ts` as plain worklets, so it is unit tested without a device.

Props: `width`, `height`, `backdrop` (a function returning a Skia shader node), `overlay` (RN content above the canvas, not bent by the lens), `radius`, `strength`, `aberration`, `label`, `onMove`, `onFeedback` (`grab`, `release`), `reducedMotion`. The backdrop is sampled by position, so it should fill the box.

Accessibility: the surface is one adjustable element with a label and hint. Screen reader actions (left, right, up, down) and the arrow keys on web nudge the lens by 24 points. System Reduce Motion or `reducedMotion` removes the spring lag, the stretch and the colour fringe, and the lens follows the finger with a very short ease.

Verified: helper tests, TypeScript, Expo dependency check and web export, and the real source rendered with Skia CanvasKit on React Native Web. The shader samples the scene three times per pixel on the GPU and has not been profiled on low-end hardware. The site preview is a separate canvas adapter that runs the same math in JavaScript, not Skia.

API docs checked: https://shopify.github.io/react-native-skia/docs/shaders/overview/, https://shopify.github.io/react-native-skia/docs/shaders/runtime-shader/, https://shopify.github.io/react-native-skia/docs/animations/reanimated/
